---@return any value3 # The modelID , lodID , worldModelPositionX,Y,Z , worldModelRotationX,Y,Z and entityType parameters are returned even if hitElement is nil .
---@return Y value4 # The modelID , lodID , worldModelPositionX,Y,Z , worldModelRotationX,Y,Z and entityType parameters are returned even if hitElement is nil .
---@return any value5 # The modelID , lodID , worldModelPositionX,Y,Z , worldModelRotationX,Y,Z and entityType parameters are returned even if hitElement is nil .
function testSphereAgainstWorld(...) end

